-- Repair stock English bot messages imported as Windows-1252 instead of UTF-8.
-- Live evidence: "It's good to meet you." was stored with apostrophe bytes
-- C3A2E282ACE284A2 (the UTF-8 encoding of the mojibake form of U+2019).
-- The earlier migration matched E28099 and therefore left these rows unchanged.
-- Match complete stock name/text pairs; preserve custom text, localized columns
-- and message metadata. New migration: do not alter an already-recorded hash.
SET @repair_encoded_bot_apostrophes = IF(
    EXISTS(SELECT 1 FROM information_schema.tables
           WHERE table_schema = DATABASE() AND table_name = 'ai_playerbot_texts'),
    'UPDATE `ai_playerbot_texts` AS t JOIN (SELECT 0x7461756e74 AS name, 0x49c3a2e282ace284a26d20736f7272792c2049206469646ec3a2e282ace284a274207265616c697a65203c7461726765743e207765726520616e2065787065727420696e2065766572797468696e672e AS old_text, 0x49276d20736f7272792c2049206469646e2774207265616c697a65203c7461726765743e207765726520616e2065787065727420696e2065766572797468696e672e AS new_text UNION ALL SELECT 0x7461756e74 AS name, 0x49c3a2e282ace284a26d20736f7272792c20627574203c7461726765743e2773206f70696e696f6e206973206a757374206e6f7420776f727468206d792074696d652e AS old_text, 0x49276d20736f7272792c20627574203c7461726765743e2773206f70696e696f6e206973206a757374206e6f7420776f727468206d792074696d652e AS new_text UNION ALL SELECT 0x7461756e74 AS name, 0x4974c3a2e282ace284a27320616d7573696e6720686f77203c7461726765743e207468696e6b7320736f20686967686c79206f66207468656d73656c766573207768656e2065766572796f6e6520656c73652073656573207269676874207468726f756768207468656d2e AS old_text, 0x4974277320616d7573696e6720686f77203c7461726765743e207468696e6b7320736f20686967686c79206f66207468656d73656c766573207768656e2065766572796f6e6520656c73652073656573207269676874207468726f756768207468656d2e AS new_text UNION ALL SELECT 0x7461756e74 AS name, 0x4974c3a2e282ace284a273206375746520686f77203c7461726765743e20747269657320746f20616374206c696b652074686579206b6e6f772065766572797468696e672e AS old_text, 0x49742773206375746520686f77203c7461726765743e20747269657320746f20616374206c696b652074686579206b6e6f772065766572797468696e672e AS new_text UNION ALL SELECT 0x7461756e74 AS name, 0x57686174c3a2e282ace284a2732077726f6e672077697468203c7461726765743e3f AS old_text, 0x5768617427732077726f6e672077697468203c7461726765743e3f AS new_text UNION ALL SELECT 0x7461756e74 AS name, 0x3c7461726765743e2073686f756c646ec3a2e282ace284a274206861766520646f6e65207468617421 AS old_text, 0x3c7461726765743e2073686f756c646e2774206861766520646f6e65207468617421 AS new_text UNION ALL SELECT 0x7461756e74 AS name, 0x446f6ec3a2e282ace284a2742074616c6b20746f206d65206c696b6520746861742c203c7461726765743e21 AS old_text, 0x446f6e27742074616c6b20746f206d65206c696b6520746861742c203c7461726765743e21 AS new_text UNION ALL SELECT 0x7461756e74 AS name, 0x57686174c3a2e282ace284a273203c7461726765743e27732070726f626c656d3f AS old_text, 0x576861742773203c7461726765743e27732070726f626c656d3f AS new_text UNION ALL SELECT 0x7461756e74 AS name, 0x4920646f6ec3a2e282ace284a2742077616e7420746f20736565203c7461726765743e2773206661636521 AS old_text, 0x4920646f6e27742077616e7420746f20736565203c7461726765743e2773206661636521 AS new_text UNION ALL SELECT 0x68656c6c6f AS name, 0x4974c3a2e282ace284a27320676f6f6420746f206d65657420796f752e AS old_text, 0x4974277320676f6f6420746f206d65657420796f752e AS new_text UNION ALL SELECT 0x68656c6c6f AS name, 0x57686174c3a2e282ace284a2732075703f AS old_text, 0x5768617427732075703f AS new_text UNION ALL SELECT 0x68656c6c6f AS name, 0x486f77c3a2e282ace284a27320697420676f696e673f AS old_text, 0x486f77277320697420676f696e673f AS new_text UNION ALL SELECT 0x68656c6c6f AS name, 0x4865792c20686f77c3a2e282ace284a27320796f75722064617920676f696e673f AS old_text, 0x4865792c20686f77277320796f75722064617920676f696e673f AS new_text UNION ALL SELECT 0x68656c6c6f AS name, 0x4865792c204920636f756c646ec3a2e282ace284a2742068656c7020627574206e6f7469636520796f752c20686f77c3a2e282ace284a27320697420676f696e673f AS old_text, 0x4865792c204920636f756c646e27742068656c7020627574206e6f7469636520796f752c20686f77277320697420676f696e673f AS new_text UNION ALL SELECT 0x68656c6c6f AS name, 0x48692c2049c3a2e282ace284a26d206e65772061726f756e6420686572652e204861766520796f75206265656e2068657265206c6f6e673f AS old_text, 0x48692c2049276d206e65772061726f756e6420686572652e204861766520796f75206265656e2068657265206c6f6e673f AS new_text UNION ALL SELECT 0x68656c6c6f AS name, 0x48656c6c6f2c20636f756c6420796f752074656c6c206d65207468652074696d652c20706c656173653f2049c3a2e282ace284a26d206a757374206d616b696e6720636f6e766572736174696f6e2e AS old_text, 0x48656c6c6f2c20636f756c6420796f752074656c6c206d65207468652074696d652c20706c656173653f2049276d206a757374206d616b696e6720636f6e766572736174696f6e2e AS new_text UNION ALL SELECT 0x68656c6c6f AS name, 0x4920686f706520796f75c3a2e282ace284a2726520686176696e6720612070726f64756374697665206461792e AS old_text, 0x4920686f706520796f7527726520686176696e6720612070726f64756374697665206461792e AS new_text UNION ALL SELECT 0x68656c6c6f AS name, 0x4974c3a2e282ace284a27320616e20686f6e6f7220746f2062652068657265207769746820796f752e AS old_text, 0x4974277320616e20686f6e6f7220746f2062652068657265207769746820796f752e AS new_text UNION ALL SELECT 0x676f6f64627965 AS name, 0x446f6ec3a2e282ace284a27420646f20616e797468696e67204920776f756c646ec3a2e282ace284a27420646f21 AS old_text, 0x446f6e277420646f20616e797468696e67204920776f756c646e277420646f21 AS new_text UNION ALL SELECT 0x676f6f64627965 AS name, 0x57656c6c2c206974c3a2e282ace284a273206265656ec3a2e282acc2a620696e746572657374696e672e2053656520796f752061726f756e642c20492067756573732e AS old_text, 0x57656c6c2c2069742773206265656ee280a620696e746572657374696e672e2053656520796f752061726f756e642c20492067756573732e AS new_text UNION ALL SELECT 0x676f6f64627965 AS name, 0x416c72696768742c2049c3a2e282ace284a26c6c206c6561766520796f7520746f2069742e20446f6ec3a2e282ace284a274206c65742074686520646f6f722068697420796f75206f6e2074686520776179206f75742e AS old_text, 0x416c72696768742c2049276c6c206c6561766520796f7520746f2069742e20446f6e2774206c65742074686520646f6f722068697420796f75206f6e2074686520776179206f75742e AS new_text UNION ALL SELECT 0x676f6f64627965 AS name, 0x476f6f642072696464616e63652e20446f6ec3a2e282ace284a27420636f6d65206261636b2e AS old_text, 0x476f6f642072696464616e63652e20446f6e277420636f6d65206261636b2e AS new_text UNION ALL SELECT 0x676f6f64627965 AS name, 0x49c3a2e282ace284a26d20646f6e6520686572652e2054616b652063617265c3a2e282acc2a620492067756573732e AS old_text, 0x49276d20646f6e6520686572652e2054616b652063617265e280a620492067756573732e AS new_text UNION ALL SELECT 0x676f6f64627965 AS name, 0x436174636820796f75206c617465723f204e6f2c20646f6ec3a2e282ace284a2742e20506c656173652e AS old_text, 0x436174636820796f75206c617465723f204e6f2c20646f6e27742e20506c656173652e AS new_text) AS fixes ON BINARY t.name = fixes.name AND BINARY t.text = fixes.old_text SET t.text = CONVERT(fixes.new_text USING utf8mb4)',
    'SELECT 1');
PREPARE repair_encoded_bot_apostrophes_stmt FROM @repair_encoded_bot_apostrophes;
EXECUTE repair_encoded_bot_apostrophes_stmt;
DEALLOCATE PREPARE repair_encoded_bot_apostrophes_stmt;
SET @repair_encoded_bot_apostrophes = NULL;
